
  create table "public"."data_accounts" (
    "id" bigint generated by default as identity not null,
    "code" character varying(50),
    "name" character varying(100),
    "email" character varying(100),
    "address" character varying(100),
    "district" character varying(100),
    "localy" character varying(100),
    "phone_num" character varying(50),
    "tax_position_id" bigint,
    "discount" numeric(9,2),
    "tax_num" character varying(50),
    "gross_income" character varying(50),
    "is_client" boolean,
    "is_provider" boolean,
    "is_disabled" boolean,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    "tax_num_2" character varying
      );



  create table "public"."data_conditions_types" (
    "id" bigint generated by default as identity not null,
    "desc" character varying(100),
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );



  create table "public"."data_documents" (
    "id" bigint generated by default as identity not null,
    "desc" character varying(100),
    "data_sequence_id" bigint,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );



  create table "public"."data_sequences" (
    "id" bigint generated by default as identity not null,
    "letter" character(1),
    "point" smallint,
    "last_number" integer,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );



  create table "public"."data_tax_positions" (
    "id" bigint generated by default as identity not null,
    "desc" character varying(50),
    "vat_included" boolean,
    "is_disabled" boolean,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );



  create table "public"."data_vat_types" (
    "id" bigint generated by default as identity not null,
    "desc" character varying(50),
    "value" numeric(9,2),
    "is_disabled" boolean,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );



  create table "public"."sales_quotes" (
    "id" bigint generated by default as identity not null,
    "account_id" bigint,
    "data_document_id" bigint,
    "date" timestamp without time zone,
    "address" character varying(100),
    "data_condition_type_id" bigint,
    "data_tax_position_id" bigint,
    "phone_num" character varying(50),
    "motor_id" bigint,
    "reference" character varying(100),
    "purchace_order_num" character varying(50),
    "list" character varying(100),
    "letter" character(1),
    "point" smallint,
    "number" integer,
    "is_model" bit(1),
    "concept_subtotal" numeric(18,2),
    "concept_discount" numeric(9,2),
    "article_subtotal" numeric(18,2),
    "article_discount" numeric(9,2),
    "general_discount" numeric(9,2),
    "general_recharge" numeric(9,2),
    "general_subtotal" numeric(18,2),
    "general_vat" numeric(9,2),
    "g_vat_subtotal" numeric(18,2),
    "reduced_vat" numeric(9,2),
    "r_vat_subtotal" numeric(18,2),
    "total" numeric(18,2),
    "observations" character varying(100),
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );



  create table "public"."sales_quotes_items" (
    "id" bigint generated by default as identity not null,
    "sales_quote_id" bigint,
    "stock_art_id" bigint,
    "is_concept" boolean,
    "quantity" numeric(18,2),
    "completed" numeric(18,2),
    "vat_value" numeric(9,2),
    "price" numeric(18,2),
    "total" numeric(18,2),
    "comment" character varying(100),
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );



  create table "public"."stock_articles" (
    "id" bigint generated by default as identity not null,
    "code" character varying(50),
    "measure" character varying(50),
    "desc" character varying(100),
    "is_concept" boolean,
    "stock" numeric(18,2),
    "min" numeric(18,2),
    "max" numeric(18,2),
    "account_id" bigint,
    "category_id" bigint,
    "class_id" bigint,
    "vat_type_id" bigint,
    "is_disabled" boolean,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );



  create table "public"."stock_categories" (
    "id" bigint generated by default as identity not null,
    "desc" character varying(50),
    "category" character varying(50),
    "subcategory" character varying(50),
    "section" character varying(50),
    "is_disabled" boolean,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );



  create table "public"."stock_classes" (
    "id" bigint generated by default as identity not null,
    "desc" character varying(50),
    "is_disabled" boolean,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );



  create table "public"."stock_lists" (
    "id" bigint generated by default as identity not null,
    "desc" character varying(100),
    "is_disabled" boolean,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );



  create table "public"."stock_motors" (
    "id" bigint generated by default as identity not null,
    "code" character varying(50),
    "desc" character varying(100),
    "list_id" bigint,
    "is_disabled" boolean,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );



  create table "public"."stock_prices" (
    "id" bigint generated by default as identity not null,
    "article_id" bigint,
    "list_id" bigint,
    "cost" numeric(18,2),
    "margin" numeric(9,2),
    "price" numeric(18,2),
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
      );


